package com.vault.config;
import jakarta.servlet.http.HttpServletRequest;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler{ @ExceptionHandler(ResponseStatusException.class)public ResponseEntity<?> status(ResponseStatusException e,HttpServletRequest r){int s=e.getStatusCode().value();return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now(),"status",s,"message",Objects.toString(e.getReason(),"Request failed"),"path",r.getRequestURI()));}@ExceptionHandler(MethodArgumentNotValidException.class)public ResponseEntity<?> invalid(MethodArgumentNotValidException e,HttpServletRequest r){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"message","Please check the submitted fields","path",r.getRequestURI()));}@ExceptionHandler(Exception.class)public ResponseEntity<?> other(Exception e,HttpServletRequest r){return ResponseEntity.status(500).body(Map.of("timestamp",Instant.now(),"status",500,"message","Something went wrong. Please try again.","path",r.getRequestURI()));}}
